          activeOpacity={0.85}>
          <Icon name="check-circle" size={18} color={colors.rootBg} style={{ marginRight: 8 }} />
          <Text style={s.ackBtnText}> {t('account.acknowledge')} </Text>
        </TouchableOpacity>
      </View>
