        {/* â”€â”€ Camera oval frame â”€â”€ */}
        <View style={styles.cameraFrameWrap}>
          <View style={[styles.ovalGuide, captured && styles.ovalGuideCaptured]}>
            {captured ?
            <View style={styles.capturedState}>
