        {/* â”€â”€ Selfie Guidelines Card â”€â”€ */}
        <GlassCard style={styles.card}>
          <Text style={styles.cardTitle}>{t("content.application_kyc.SelfieCaptureContent.SELFIE_GUIDELINES_TITLE").toUpperCase()}</Text>
          <View style={styles.guideList}>
