  }, [scale, opac]);

  return (
    <SafeAreaView style={s.root} edges={['top', 'bottom']}>
      <StatusBar barStyle="light-content" backgroundColor={colors.rootBg} />

      <Animated.View style={[s.body, { opacity: opac }]}>
