          activeOpacity={0.75}>
            <View style={[s.reasonRadio, selected === r && s.reasonRadioActive]}>
              {selected === r && <View style={s.reasonRadioInner} />}
            </View>
            <Text style={[s.reasonLabel, selected === r && s.reasonLabelActive]}>{r}</Text>
          </TouchableOpacity>
        )}

        {/* Earnings summary */}
