          <View style={s.card}>
            {CONSEQUENCES.map((c, i) =>
            <View key={i}>
                {i > 0 && <View style={s.sep} />}
                <View style={s.consequenceRow}>
                  <View style={s.xIconWrap}>
                    <Icon name="close" size={14} color="#E74C3C" />
